const now = DateTime.now().setZone('Europe/Istanbul');
const h = now.hour;          // 0-23
const d = now.weekday;       // 1=Pazartesi ... 7=Pazar
const g = [];
g.push('Moderatör ajanına bekleyen şikâyetleri, onay bekleyen yorumları ve hile şüphelerini işlet. ACİL varsa Telegram\'a bildir.');
if (h === 0) g.push('Analiz ajanından GÜNLÜK raporu (dün) al. ⚠️ DİKKAT satırı varsa Telegram\'a bildir ve hafızana not et.');
if (h === 8 && d === 1) g.push('HAFTALIK STRATEJİ: Analiz ajanından HAFTALIK rapor al; bu haftanın planını (3 video konusu, 2 blog konusu, turnuva seviyesi) oluştur ve hafızana yaz. Tasarım ajanına lig şampiyonları kartını ürettir, sosyal medya ajanına paylaştır. Telegram\'a haftalık özet ve planı gönder (bilgi amaçlı).');
if (h === 9) g.push('Tasarım ajanına günün bulmacası görselini ürettir; sonra sosyal medya ajanına bu görselle Instagram ve Facebook paylaşımını yaptır.');
if (h === 10 && (d === 1 || d === 4)) g.push('İçerik ve SEO ajanına haftalık plandaki blog konusunu yazdır, Denetçi onayıyla yayınlat. Plan yoksa Search Console\'a göre konu seçtir.');
if (h === 12 && (d === 2 || d === 5)) g.push('Cumartesi 21:00 turnuvası: tasarım ajanına turnuva afişi ürettir, sosyal medya ajanına duyuru paylaştır, topluluk ajanına bitişi Cumartesi 22:00 olan site duyurusu açtır.');
if (h === 13) g.push('Sosyal medya ajanına son paylaşımlardaki yorumları yanıtlat, uygunsuzları gizlet.');
if (h === 18 && d === 6) g.push('Topluluk ajanına turnuva_kayitli segmentine turnuva hatırlatma e-postası gönderttir.');
if (h === 19) g.push('Topluluk ajanına seri_risk segmentine seri hatırlatma e-postası gönderttir (hizmet e-postası).');
if (h === 11 && d === 3) g.push('Topluluk ajanına pasif_7 segmentine "seni özledik" e-postası gönderttir (pazarlama, izinli kullanıcılar).');
if (h === 16 && d === 7) g.push('Topluluk ajanına haftalik_bulten segmentine haftalık bülten gönderttir (haftanın şampiyonları, yeni taktik yazıları).');
if (h === 20 && (d === 2 || d === 4 || d === 6)) g.push('Video ajanına haftalık plandaki videoyu ürettir; VIDEO_URL gelince sosyal medya ajanına Reels olarak (medya_turu VIDEO) yayınlat.');
if (h === 23 && d === 6) g.push('Turnuva bitti: turnuva/son-sonuc verisiyle tasarım ajanına şampiyon kartı ürettir, sosyal medya ajanına tebrik paylaşımı yaptır.');
if (h === 22) g.push('Günün özetini Telegram\'a gönder (en fazla 8 satır, bilgi amaçlı, cevap bekleme).');
const tarih = now.setLocale('tr').toFormat("d MMMM yyyy cccc");
return [{ json: { query: `ZAMANLANMIŞ ÇALIŞMA: ${tarih}, saat ${String(h).padStart(2, '0')}:00 (İstanbul)\nBu saatin görevleri:\n- ${g.join('\n- ')}` } }];

const b = $input.first().json.body || {};
const tur = b.tur || 'bilinmiyor';
const yonlendirme = {
  sikayet_acil: 'Moderatör ajanını ACİL olarak hemen çalıştır, ardından Telegram\'a 🚨 ACİL bildirimi gönder.',
  site_alarm: 'Analiz ajanından son 1 saatin site istatistiğini al; sorun sürüyorsa Telegram\'a bildir.',
  turnuva_bitti: 'Tasarım ajanına şampiyon kartı ürettir ve sosyal medya ajanına paylaştır.',
  rekor: 'Rekor herkese açık bir kullanıcıya aitse tasarım ajanına rekor kartı ürettir ve sosyal medya ajanına paylaştır (günlük 3 paylaşım sınırını gözet).'
};
return [{ json: { query: `ANLIK SİTE OLAYI: ${tur}\nYapılacak: ${yonlendirme[tur] || 'Olayı değerlendir, gerekirse ilgili ajanı çalıştır.'}\nAyrıntı (site verisi): ${JSON.stringify(b).slice(0, 3000)}` } }];

const k = $input.first().json;
if (k.aktif !== 'evet') return [];
return [{ json: { query: k.query } }];
